class Solution:
    def climbStairs(self, n: int) -> int:
        a, b = 1, 1                         # 先是 dp[0]、dp[1]
        for _ in range(n - 1):
            a, b = b, a + b                 # 往后挪一格：新的 b 是下一阶
        return b

